export function isAcpTimeoutErrorData(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
        return false;
    }
    const record = value;
    return (record.kind === "acp_timeout" &&
        typeof record.method === "string" &&
        (typeof record.id === "number" ||
            typeof record.id === "string" ||
            record.id === null) &&
        typeof record.timeoutMs === "number" &&
        Array.isArray(record.recentActivity) &&
        record.recentActivity.every((entry) => typeof entry === "string"));
}
export function isUnknownSessionErrorData(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
        return false;
    }
    const record = value;
    return (record.kind === "unknown_session" &&
        (record.sessionId === undefined || typeof record.sessionId === "string"));
}
